CREATE TABLE CW_INVOICE_MAIL_TEMPLATE (SINGLETON_ID SMALLINT NOT NULL PRIMARY KEY, SUBJECT_TEMPLATE VARCHAR(500) NOT NULL, BODY_TEMPLATE VARCHAR(10000) NOT NULL, UPDATED_AT TIMESTAMP NOT NULL, CONSTRAINT CW_INV_MAIL_SINGLETON CHECK (SINGLETON_ID = 1));
CREATE TABLE CW_INVOICE_MAIL_LOG (ID BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY, INVOICE_ID BIGINT NOT NULL, RECIPIENT VARCHAR(320) NOT NULL, SUBJECT VARCHAR(500) NOT NULL, SENT_AT TIMESTAMP NOT NULL, ATTACHED_XML SMALLINT NOT NULL, CONSTRAINT CW_INV_MAIL_FK FOREIGN KEY (INVOICE_ID) REFERENCES CW_INVOICE(ID));
